WITH cleaned AS (SELECT id, order_id, product_id, quantity, unit_price, quantity - unit_price line_total, ROUND(quantity * 1.1, 2) adjusted_quantity FROM order_items WHERE product_id IS NOT NULL) SELECT dim.status, dim.channel, COUNT(*) AS num_rows, MAX(src.quantity) AS max_quantity FROM cleaned src LEFT JOIN orders dim ON src.order_id = dim.id GROUP BY CUBE (dim.status, dim.channel) ORDER BY num_rows DESC;
